import { Component, signal, inject } from '@angular/core'; // ⚡ Added inject here
import { FormBuilder, FormGroup, Validators, ReactiveFormsModule } from '@angular/forms';
import { HttpClient } from '@angular/common/http'; // Removed HttpClientModule from imports
import { Router } from '@angular/router';
import { CommonModule } from '@angular/common';
import { RouterLink } from '@angular/router'; 

@Component({
  selector: 'app-login',
  standalone: true,
  imports: [
    RouterLink,
    CommonModule,
    ReactiveFormsModule
    // HttpClientModule completely removed so your global interceptor manages the request
  ],
  templateUrl: './login.html'
})
export class Login {
  private fb = inject(FormBuilder);
  private http = inject(HttpClient);
  private router = inject(Router);

  loginForm: FormGroup;
  errorMessage = signal<string>(''); 
  isSubmitting = false;
  private apiUrl = '/admin.php'; 

  constructor() {
    this.loginForm = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      password: ['', Validators.required]
    });
  }

  onSubmit(): void {
    if (this.loginForm.invalid) {
      this.loginForm.markAllAsTouched();
      return;
    }

    this.isSubmitting = true;
    this.errorMessage.set(''); 

    const payload = {
      email: this.loginForm.value.email,
      password: this.loginForm.value.password
    };

    // The interceptor combines your base URL with this string: e.g. http://192.168.0.115:8080/admin.php?action=login
    this.http.post<any>(`${this.apiUrl}?action=login`, payload).subscribe({
      next: (res) => {
        if (res.status === 'success') {
          // 💾 Save everything to localStorage safely
          localStorage.setItem('userId', res.user_id.toString());
          localStorage.setItem('firstName', res.first_name);
          localStorage.setItem('role', res.role);
          localStorage.setItem('status', res.account_status || res.status_field || 'pending');

          if (res.role === 'admin') {
            this.router.navigate(['/admin']); 
          } else {
            this.router.navigate(['/portal']);
          }
        } else {
          this.errorMessage.set(res.message || 'Invalid email or password');
        }
        this.isSubmitting = false;
      },
      error: (err) => {
        console.error(err);
        this.errorMessage.set('Unable to connect to server');
        this.isSubmitting = false;
      }
    });
  }
}