import { Component, OnInit, Injectable, signal, computed, Output, EventEmitter } from '@angular/core';
import { HttpClient, HttpClientModule } from '@angular/common/http';
import { CommonModule } from '@angular/common';

export interface Alumni {
  id: number;
  First_name: string;
  photo?: string;
  Email?: string;
  Phone_number?: string;
  Employer?: string;
  Role?: string;
  Programme?: string;
  MembershipOrg?: string;
  MembershipID?: string;
  LinkedIn?: string;
  Address?: string;
  home_county?: string;
  YearJoined?: number;
  GraduationYear?: string;
}

interface ApiResponse {
  status: string;
  data: Alumni[];
  meta?: {
    total: number;
    page: number;
    limit: number;
    totalPages: number;
  };
}

@Injectable({
  providedIn: 'root'
})
export class AlumniService {
  private apiUrl = 'http://192.168.0.115:8080/get-alumni.php';
  constructor(private http: HttpClient) {}

  getAlumni(loggedInUserId: number, page: number = 1, limit: number = 8) {
    return this.http.get<ApiResponse>(
      `${this.apiUrl}?exclude_id=${loggedInUserId}&page=${page}&limit=${limit}`
    );
  }
}

@Component({
  selector: 'app-profile',
  standalone: true, 
  imports: [CommonModule, HttpClientModule],
  templateUrl: './profile.html'
})
export class Profile implements OnInit {
  
  @Output() onStartChat = new EventEmitter<Alumni>();

  // 🚦 State Signals
  alumniList = signal<Alumni[]>([]); 
  errorMessage = signal<string>('');
  searchQuery = signal<string>('');
  isLoading = signal<boolean>(false); // 🆕 Added loading state signal

  // 📄 Pagination Signals
  currentPage = signal<number>(1);
  totalPages = signal<number>(1);
  pageSize = 8; 
  loggedInUserId: number = 0;

  // ⚡ Computed Search Filter
  filteredAlumniList = computed(() => {
    const query = this.searchQuery().toLowerCase().trim();
    const allAlumni = this.alumniList();

    if (!query) {
      return allAlumni;
    }

    return allAlumni.filter(alumni => 
      alumni.First_name && alumni.First_name.toLowerCase().includes(query)
    );
  });

  constructor(private alumniService: AlumniService) {}

  ngOnInit(): void {
    this.loggedInUserId = Number(localStorage.getItem('userId') || sessionStorage.getItem('user_id'));
    this.fetchAlumniPage();
  }

  // Isolation fetch helper
  fetchAlumniPage(): void {
    this.isLoading.set(true);       // 🆕 Start loading
    this.errorMessage.set('');       // Clear previous errors on new attempt

    this.alumniService.getAlumni(this.loggedInUserId, this.currentPage(), this.pageSize).subscribe({
      next: (res) => {
        if (res.status === 'success') {
          this.alumniList.set(res.data);
          if (res.meta) {
            this.totalPages.set(res.meta.totalPages);
          }
        } else {
          this.errorMessage.set('No alumni segments found.');
          this.alumniList.set([]);
        }
        this.isLoading.set(false);   // 🆕 Stop loading on success
      },
      error: (err) => {
        console.error('Failed to load roster records:', err);
        this.errorMessage.set('Could not establish synchronization stream.');
        this.isLoading.set(false);   // 🆕 Stop loading on error
      }
    });
  }

  goToPage(page: number): void {
    // Prevent navigating if a request is already ongoing
    if (page >= 1 && page <= this.totalPages() && !this.isLoading()) {
      this.currentPage.set(page);
      this.fetchAlumniPage();
    }
  }

  onSearchChange(event: Event): void {
    const inputElement = event.target as HTMLInputElement;
    this.searchQuery.set(inputElement.value);
  }

  triggerDirectMessage(alumni: Alumni): void {
    this.onStartChat.emit(alumni);
  }
}