import { Component, OnInit, OnDestroy, signal, inject } from '@angular/core';
import { RouterLink } from '@angular/router';
import { HttpClient, HttpClientModule } from '@angular/common/http';
import { CommonModule } from '@angular/common';

// 🌟 Define an interface representing your database row properties
interface MediaAsset {
  id: number;
  title: string;
  alt_text: string;
  image_path: string;
}

@Component({
  selector: 'app-home',
  standalone: true,
  imports: [RouterLink, HttpClientModule, CommonModule],
  templateUrl: './home.html',
  styleUrl: './home.css',
})
export class Home implements OnInit, OnDestroy {
  private http = inject(HttpClient);
  private apiEndpoint = 'http://192.168.0.115:8080/admin.php';

  // 🌟 FIX: Change from signal<string[]>([]) to signal<MediaAsset[]>([])
  sliderImages = signal<MediaAsset[]>([]);
  currentSlide = signal<number>(0);
  
  private autoPlayTimer: any;

  ngOnInit() {
    this.fetchSliderImages();
  }

  fetchSliderImages() {
    this.http.get<any>(`${this.apiEndpoint}?action=getMediaAssets`)
      .subscribe({
        next: (res) => {
          if (res && res.status === 'success' && res.data.length > 0) {
            // 🌟 Directly assign the structural array of objects
            this.sliderImages.set(res.data);
            this.startAutoPlay();
          }
        },
        error: (err) => console.error("Slider fetch operation aborted:", err)
      });
  }

  nextSlide() {
    if (this.sliderImages().length === 0) return;
    this.currentSlide.update((index) => 
      index === this.sliderImages().length - 1 ? 0 : index + 1
    );
  }

  prevSlide() {
    if (this.sliderImages().length === 0) return;
    this.currentSlide.update((index) => 
      index === 0 ? this.sliderImages().length - 1 : index - 1
    );
  }

  startAutoPlay() {
    if (this.autoPlayTimer) clearInterval(this.autoPlayTimer);
    this.autoPlayTimer = setInterval(() => {
      this.nextSlide();
    }, 4000);
  }

  ngOnDestroy() {
    if (this.autoPlayTimer) {
      clearInterval(this.autoPlayTimer);
    }
  }
}