import { Component, OnInit, signal } from '@angular/core';
import { HttpClient, HttpClientModule } from '@angular/common/http';
import { CommonModule } from '@angular/common';

interface UserProfileResponse {
  status: string;
  user: any;
  academic: any;
  current: any;
  history: any[];
  education: any;
  membership: any;
  social: any;
}

@Component({
  selector: 'app-dashboard',
  templateUrl: './dasboard.html',
  standalone: true,
  imports: [
    CommonModule,
    HttpClientModule
  ]
})
export class Dashboard implements OnInit {

  userProfile = signal<UserProfileResponse | null>(null);
  private apiUrl = 'http://192.168.0.115:8080/admin.php';

  constructor(private http: HttpClient) {}

  ngOnInit() {
    // FIX: Change from sessionStorage to localStorage using the correct 'userId' key
    const userId = Number(localStorage.getItem('userId')) || 0;
    
    if (userId > 0) {
      this.getUserProfile(userId);
    } else {
      console.warn("Dashboard loaded but no valid userId was found in localStorage.");
    }
  }

  getUserProfile(userId: number) {
    this.http
      .get<UserProfileResponse>(`${this.apiUrl}?action=getdetailsAlumni&user_id=${userId}`)
      .subscribe({
        next: (data) => {
          console.log("Dashboard profile data loaded:", data);
          this.userProfile.set(data);
        },
        error: (err) => {
          console.error("Failed to load dashboard statistics:", err);
        }
      });
  }
}